{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_policy.privesc18-PassExistingRoleToNewGlueDevEndpoint",
      "severity": "MEDIUM",
      "explanation": "The attached IAM policy may allow full IAM privileges, which can lead to privilege escalation or unauthorized access if not properly scoped."
    }
  ],
  "patched_code": "resource "aws_iam_user_policy_attachment" "privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy" {
  user       = aws_iam_user.privesc18-PassExistingRoleToNewGlueDevEndpoint-user.name
  policy_arn = aws_iam_policy.privesc18-PassExistingRoleToNewGlueDevEndpoint.arn
}

resource "aws_iam_policy" "privesc18-PassExistingRoleToNewGlueDevEndpoint" {
  name        = "privesc18-PassExistingRoleToNewGlueDevEndpoint"
  description = "Policy for Glue Dev Endpoint with least privilege"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "glue:CreateDevEndpoint",
        "glue:GetDevEndpoint",
        "glue:UpdateDevEndpoint",
        "glue:DeleteDevEndpoint"
      ],
      "Resource": "arn:aws:glue:*:*:devEndpoint/*"
    }
  ]
}
EOF
}
",
  "fix_summary": "Scoped the IAM policy to allow only specific Glue Dev Endpoint actions instead of potentially allowing full IAM privileges."
}
